{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — A Sound Bath Experience in {{CITY}}, {{STATE}}</title>
  <meta name="description" content="A premium sensory sound bath offering immersive group events and private sessions. What to bring, flow, and safety details included.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="layout-split">
  <header class="site-header">
    <div class="brand">
      <svg class="logo" width="48" height="48" viewBox="0 0 48 48" aria-hidden="true"><defs><linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#6f4ff2"/><stop offset="1" stop-color="#00d4ff"/></linearGradient></defs><rect width="48" height="48" rx="8" fill="url(#g1)"></rect><path d="M12 34c6-12 24-12 30 0" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round"/></svg>
      <div class="brand-copy">
        <strong class="business">{{BUSINESS_NAME}}</strong>
        <small class="tag">{{TAGLINE}}</small>
      </div>
    </div>
    <nav class="nav" aria-label="Primary Navigation">
      <button class="nav-toggle" aria-expanded="false">☰</button>
      <ul class="nav-list">
        <li><a href="index.html">Home</a></li>
        <li><a href="events.html">Events</a></li>
        <li><a href="private-sessions.html">Sessions</a></li>
        <li><a href="pricing.html">Pricing</a></li>
        <li><a href="about.html">About</a></li>
        <li><a href="book.html" class="primary">{{PRIMARY_CTA_LABEL}}</a></li>
      </ul>
    </nav>
  </header>

  <main>
    <!-- HERO -->
    <section id="hero" class="hero split-diagonal" aria-label="Hero">
      <div class="hero-left">
        <h1 class="hero-title">Sink into Sound — A Guided Immersive Sound Bath</h1>
        <p class="lede">An intensive, sensory ritual blending crystal bowls, chimes, and tuning forks to guide you into relaxed awareness. Premium cushions, curated light, and a focused facilitation make space for deep rest.</p>
        <div class="hero-ctas">
          <a class="btn btn-primary" href="book.html">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn btn-ghost" href="events.html">Next event — {{NEXT_EVENT_DATE}}</a>
        </div>
        <ul class="meta">
          <li>Facilitator: {{FACILITATOR_NAME}}</li>
          <li>Venue: {{VENUE_NAME}}, {{CITY}}</li>
        </ul>
      </div>
      <div class="hero-right">
        <svg class="pattern" viewBox="0 0 600 600" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="hGrad" x1="0" x2="1"><stop offset="0" stop-color="#f7f2ff"/><stop offset="1" stop-color="#e6fbff"/></linearGradient></defs><rect width="600" height="600" fill="url(#hGrad)"></rect><use href="assets/img/pattern.svg#pattern" x="0" y="0" width="600" height="600" opacity="0.14"/></svg>
      </div>
    </section>

    <!-- MYTH VS TRUTH -->
    <section id="myth_vs_truth" class="myth-truth">
      <h2>Myths &amp; Reality: What a Sound Bath Actually Does</h2>
      <div class="grid">
        <div class="card myth">
          <h3>Myth</h3>
          <p>It’s just pretty music you hear from a distance.</p>
        </div>
        <div class="card truth">
          <h3>Truth</h3>
          <p>It’s a sensory journey. Intentionally designed vibrations, delivered with attention, guide nervous system recalibration and altered states of restful awareness.</p>
        </div>
        <div class="card myth">
          <h3>Myth</h3>
          <p>Everyone has the same experience.</p>
        </div>
        <div class="card truth">
          <h3>Truth</h3>
          <p>Responses vary: some move, some sleep, some weep. All are supported. Sessions are curated to be deeply accessible and supportive.</p>
        </div>
      </div>
    </section>

    <!-- PILLARS -->
    <section id="pillars" class="pillars">
      <h2>Our Pillars of Care</h2>
      <div class="cols">
        <div class="pillar">
          <h4>Sensory Craft</h4>
          <p>Layered instruments — crystal bowls, a warm gong, and delicate chimes — sculpt a landscape of frequency.</p>
        </div>
        <div class="pillar">
          <h4>Intentional Facilitation</h4>
          <p>Pre-session framing, breath cues, and mid-bath check-ins create safety and depth.</p>
        </div>
        <div class="pillar">
          <h4>Premium Setting</h4>
          <p>Soft lighting, plush bolsters, and curated scent (optional) provide a ritual-grade environment.</p>
        </div>
      </div>
    </section>

    <!-- CASE NOTES (testimonials / flow) -->
    <section id="case_notes" class="case-notes">
      <h2>How a Session Flows</h2>
      <ol class="flow">
        <li><strong>Arrival &amp; Settle:</strong> You arrive 15 minutes early. We offer blankets and bolsters; set an intention.</li>
        <li><strong>Intentions &amp; Breath:</strong> Short welcome, safety notes, gentle breathing to attune to the space.</li>
        <li><strong>Main Sound Journey:</strong> 40–60 min of layered sound — tuning forks, crystal bowls, and a soft monochord or gong — with facilitatory cues.</li>
        <li><strong>Come Back Slowly:</strong> A gradual re-entry with grounding tones and a short check-in.</li>
      </ol>
      <h3>What to bring</h3>
      <ul>
        <li>A yoga mat or large blanket.</li>
        <li>Layers: socks and a sweater for changing body temperature.</li>
        <li>An eye-mask or scarf if you prefer darkness.</li>
        <li>A water bottle for after the session.</li>
      </ul>
      <div class="notes">
        <p class="disclaimer"><strong>Contraindications:</strong> Not recommended if you have uncontrolled seizures, are in the first trimester of pregnancy without clearance, or have severe cardiovascular instability. Please consult with your physician and reach out to us via {{EMAIL}} to discuss accommodations.</p>
        <p class="testimonial">“I felt like the room melted away — deep, restorative, and safe.” — M., {{CITY}}</p>
      </div>
    </section>

    <!-- FAQ -->
    <section id="faq" class="faq">
      <h2>Quick Questions</h2>
      <div class="qa">
        <button class="q" data-toggle="a1">Do I need experience for this?</button>
        <div id="a1" class="a">No prior experience required. We guide you through simple ways to set intention and relax physically.</div>
        <button class="q" data-toggle="a2">How long are events?</button>
        <div id="a2" class="a">Group events are typically 75 minutes total: arrival, 45–60 minutes of sound, and re-entry.</div>
        <button class="q" data-toggle="a3">Can I book a private session?</button>
        <div id="a3" class="a">Yes — we offer 1:1, couples, and corporate sound sessions tailored to needs on the Private Sessions page.</div>
      </div>
    </section>

    <!-- CTA -->
    <section id="cta" class="cta">
      <div class="cta-inner">
        <h2>Ready for an intensive sensory reset?</h2>
        <p>Reserve your place now — small groups, limited seats, boutique care.</p>
        <a class="btn btn-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <p class="small">Questions? Call us at <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="foot-inner">
      <p>&copy; <span id="year"></span> {{BUSINESS_NAME}} — {{CITY}}, {{STATE}}</p>
      <nav class="foot-nav">
        <a href="privacy.html">Privacy</a>
        <a href="contact.html">Contact</a>
        <a href="faq.html">FAQ</a>
      </nav>
    </div>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
