{"path":"assets/css/styles.css","content":"/* Premium + playful split diagonal layout */
:root{--primary:#6f4ff2;--accent:#00d4ff;--muted:#7d7d93;--bg:#fbfbff;--radius:12px}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; margin:0;background:linear-gradient(180deg,var(--bg),#f2f8ff 60%)}
.site-header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;border-bottom:1px solid rgba(110,110,140,0.06);position:sticky;top:0;background:rgba(255,255,255,0.8);backdrop-filter:blur(6px);z-index:40}
.brand{display:flex;gap:12px;align-items:center}
.brand .logo{flex:0 0 48px;border-radius:8px}
.brand-copy .business{display:block;font-weight:700}
.brand-copy .tag{font-size:12px;color:var(--muted)}
.nav{position:relative}
.nav-toggle{display:none;background:none;border:1px solid rgba(0,0,0,0.06);padding:8px;border-radius:8px}
.nav-list{list-style:none;display:flex;gap:12px;margin:0;padding:0}
.nav-list a{color:#222;text-decoration:none;padding:8px 12px;border-radius:8px}
.nav-list a.primary{background:linear-gradient(90deg,var(--primary),var(--accent));color:#fff}

/* Split diagonal hero */
.hero.split-diagonal{display:grid;grid-template-columns:1fr 380px;gap:0;align-items:stretch;padding:48px 6%;min-height:64vh;position:relative}
.hero-left{padding:36px}
.hero-title{font-size:clamp(28px,4.2vw,48px);margin:0 0 12px;color:var(--primary)}
.lede{color:#444;margin:0 0 18px;font-size:16px}
.hero-ctas{display:flex;gap:12px;margin:18px 0}
.btn{display:inline-block;padding:12px 16px;border-radius:10px;text-decoration:none;font-weight:600}
.btn-primary{background:linear-gradient(90deg,var(--primary),var(--accent));color:#fff}
.btn-ghost{background:transparent;border:1px solid rgba(0,0,0,0.06)}
.btn-cta{background:var(--primary);color:#fff;padding:14px 22px;border-radius:14px}
.meta{list-style:none;padding:0;margin:12px 0 0;color:var(--muted);font-size:14px}

.hero-right{position:relative;overflow:hidden;border-radius:20px;margin-left:auto;margin-right:6%}
.hero-right .pattern{width:100%;height:100%;display:block}

/* Diagonal overlay */
.layout-split::before{content:'';position:fixed;inset:0;pointer-events:none;background:linear-gradient(135deg,transparent 45%,rgba(111,79,242,0.04) 45%,rgba(0,212,255,0.03) 55%)}

/* Myth vs truth */
.myth-truth{padding:48px 6%;background:linear-gradient(180deg,transparent,#ffffff);}
.myth-truth h2{color:#222;margin:0 0 18px}
.myth-truth .grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
.card{padding:18px;border-radius:12px;background:linear-gradient(180deg,#fff,#fbfbff);box-shadow:0 6px 18px rgba(12,12,20,0.04)}
.card.myth{opacity:0.95;border:1px dashed rgba(111,79,242,0.06)}
.card.truth{border-left:4px solid var(--primary)}

/* Pillars */
.pillars{padding:40px 6%;}
.pillars h2{margin:0 0 16px}
.pillars .cols{display:flex;gap:16px}
.pillar{flex:1;background:white;padding:18px;border-radius:12px;box-shadow:0 10px 30px rgba(100,90,140,0.04)}
.pillar h4{margin:0 0 8px;color:var(--primary)}

/* Case notes */
.case-notes{padding:40px 6%;}
.case-notes h2{margin:0 0 12px}
.flow{background:linear-gradient(90deg,#fff,#fbfdff);padding:18px;border-radius:12px;list-style-position:inside}
.case-notes .notes{margin-top:12px}
.disclaimer{background:#fff4f6;border-left:4px solid #ff6b6b;padding:12px;border-radius:8px}
.testimonial{font-style:italic;color:#555;margin-top:8px}

/* FAQ */
.faq{padding:40px 6%;background:linear-gradient(180deg,#f9fbff,#fff)}
.faq h2{margin:0 0 12px}
.qa{display:block}
.q{display:block;width:100%;text-align:left;padding:12px;border-radius:10px;border:1px solid rgba(0,0,0,0.04);background:white;margin-top:8px}
.a{display:none;padding:12px;margin-top:6px;border-radius:8px;background:#fff;}
.a.open{display:block}

/* CTA and footer */
.cta{padding:48px 6%;background:linear-gradient(90deg,rgba(111,79,242,0.06),rgba(0,212,255,0.02));border-radius:16px;margin:24px 6%}
.cta-inner{text-align:center}
.site-footer{padding:18px 6%;font-size:14px;color:var(--muted)}
.foot-nav a{margin-left:12px;color:var(--muted);text-decoration:none}

/* Responsive */
@media(max-width:900px){
  .hero.split-diagonal{grid-template-columns:1fr;padding:28px 5%}
  .hero-right{height:200px;margin:18px 0 0;border-radius:14px}
  .nav-list{display:none}
  .nav-toggle{display:inline-block}
  .nav.open .nav-list{display:flex;flex-direction:column;position:absolute;right:0;top:56px;background:white;padding:12px;border-radius:12px;box-shadow:0 12px 40px rgba(10,10,30,0.06)}
  .pillars .cols{flex-direction:column}
}
"} 
{"path":"assets/js/main.js","content":"// Light interaction: nav toggle, FAQ accordion, inject year & next event
(function(){
  document.addEventListener('DOMContentLoaded',function(){
    // Year
    var y=document.getElementById('year');if(y) y.textContent=new Date().getFullYear();
    // Nav toggle
    var toggle=document.querySelector('.nav-toggle'), nav=document.querySelector('.nav');
    if(toggle && nav){
      toggle.addEventListener('click',function(){
        var expanded=this.getAttribute('aria-expanded')== 'true';
        this.setAttribute('aria-expanded',!expanded);
        nav.classList.toggle('open');
      });
    }
    // FAQ accordion
    document.querySelectorAll('.q').forEach(function(btn){
      btn.addEventListener('click',function(){
        var id=this.getAttribute('data-toggle');
        var panel=document.getElementById(id);
        if(!panel) return;
        panel.classList.toggle('open');
        panel.style.maxHeight = panel.classList.contains('open') ? panel.scrollHeight + 'px' : null;
      });
    });
    // Smooth scroll for internal anchors
    document.querySelectorAll('a[href^="#"]').forEach(function(a){
      a.addEventListener('click',function(e){
        e.preventDefault();
        var t=document.querySelector(this.getAttribute('href'));
        if(t) t.scrollIntoView({behavior:'smooth',block:'start'});
      });
    });
    // Inject NEXT_EVENT_DATE placeholders into any element with data-next-event
    var nexts = document.querySelectorAll('[data-next-event]');
    nexts.forEach(function(el){ el.textContent = el.textContent.replace(/\{\{NEXT_EVENT_DATE\}\}/g, ''); });
  });
})();"} 
